        currentOwner = ILPP(TARGET).owner();
        vm.label(currentOwner, "Current Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get some tokens to victim first
        // Mint some tokens to victim by impersonating the owner (who has all tokens initially)
        vm.startPrank(currentOwner);

        // Transfer some tokens to victim so we can test
        ILPP(TARGET).transfer(victim, 1000 * 10**18);

        // Step 2: Add victim to botlist
        address[] memory bots = new address[](1);
        bots[0] = victim;
        ILPP(TARGET).addBots(bots, true);

        vm.stopPrank();

        // Step 3: Verify by attempting a transfer from victim when antibot is enabled
        // First, ensure antibot is enabled (it is by default)
        // Try to transfer from victim to another address
